http://creativecommons.org/licenses/by-nc-nd/4.0/
----------------------------------------------------- */
/* Reset */
* {
	margin:0;
	padding:0;
	list-style:none;
}
/* Hyperlink */
a:link {
  	color:#999;
  	text-decoration:none;
}
a:visited {
  	color:#999;
  	text-decoration:none;
}
a:hover {
  	color:#111;
  	text-decoration:none;
	transition: all 1s linear;
	-moz-transition: all 0.3s linear;
	-webkit-transition: all 0.3s linear;
	-os-transition: all 0.3s linear;
}
a img {
  	border-width:0;
}
/* Typography */
h1, h2, 
h3, h4 {
	margin:0 auto 10px;
	padding:0;
	text-transform:normal;
	font-weight:normal;
}
h1 {
	font-size:72px;
	font-family: 'Sacramento', cursive;
	font-weight:300;
	letter-spacing:0;
	text-transform:normal;
	color:#222;
	text-align:center;
}
h2 {
	font-size:11px;
	font-family:'Open Sans', sans-serif;
	font-weight:600;
	letter-spacing:3px;
	text-transform:uppercase;
	color:#222;
	text-align:center;
}
h3 {
	font-size:32px;
	font-family: 'Sacramento', cursive;
	font-weight:300;
	color:#333;
	text-align:left;
}
h4 {
	font-size:14px;
	font-family:'Open Sans', sans-serif;
	font-weight:300;
	font-style:italic;
	color:#222;
	text-align:left;
}
/* Body */
body {
  	background:#FFF;
	border-top:3px solid #333;
	width:100%;
	height:100%;
	overflow-x:hidden;
  	margin:0 0 0 0;
	padding:0 0 0 0;
	font-size:12px;
	font-family:'Open Sans', sans-serif;
  	color:#222;
}
#header-wrapper {
  	width:100%;
	min-height:200px;
  	margin:0 auto;
}
#crosscol-wrapper {
	width:1050px;
	min-height:20px;
  	margin:0 auto 20px;
  	padding:0;
}
#outer-wrapper {
  	width:1050px;
  	margin:0 auto 100px;
 	padding:20px 0 0 0;
}
#main-wrapper {
  	width:700px;
  	float:left;
	margin:0 auto 50px;
  	word-wrap:break-word;
  	overflow:hidden;
}
#sidebar-wrapper {
  	width:300px;
  	float:right;
	margin:50px auto 50px;
  	word-wrap:break-word;
}
#footer-wrapper {
	width:100%;
	margin:0 auto;
	padding:0;
}
/* Header */
#header-inner {
  	background-position: center;
  	margin-left:auto;
  	margin-right:auto;
}
#header { 
  	text-align:center;
  	color:#333;
}
#header h1 {
	margin-top:10%;
	color:#333;
}
#header a {
  	color:#333;
  	text-decoration:none;
}
#header a:hover {
  	color:#999;
}
#header .description {
  	margin:0 auto 5px;
  	padding:10px 0 10px;
  	max-width:700px;
  	text-transform:uppercase;
  	letter-spacing:1px;
  	line-height:100%m;
  	color:#666;
	font-size:11px;
}
#header img {
  	margin-left: auto;
  	margin-right: auto;
}
/* Crosscol */
.crosscol .widget-content {
	margin:0 auto 50px;
}
.crosscol h2 {
	display:none;
}
#PageList1 ul {
    margin: 0 auto 0 auto;
}
#PageList1 li {
	background:#FFF;
	float:left;
	margin:0 30px;
	padding:5px;
	text-align:center;
	text-transform:uppercase;
	letter-spacing:1px;
	font-weight:600;
	font-size:13px;
}
#PageList1 a,
#PageList1 a:visited {
	color:#333;
}
#PageList1 a:hover {
	color:#999;
}
/* Popular posts */
.crosscol img {
	width:100%;
	height:100%;
	margin:0 auto;
	padding:0;
}
.crosscol .PopularPosts ul {
	margin: 0;
	padding: 0;
}
.crosscol .PopularPosts ul li {
	box-sizing: border-box;
	position: relative;
	padding: 0px !important;
	width:33%;
	max-height:250px;
	overflow:hidden;
	float: left;
	margin-bottom: 2%;
	-webkit-transition: all 0.5s ease 0s;
	-moz-transition: all 0.5s ease 0s;
	-ms-transition: all 0.5s ease 0s;
	-o-transition: all 0.5s ease 0s;
	transition: all 0.5s ease 0s;
}
.crosscol .PopularPosts li {
	width:33%;
	height:100%;
	margin: 0;
}
.crosscol .PopularPosts img {
	width:100%;
	object-fit: cover;
}
.crosscol .PopularPosts .item-content:hover .item-title a,
.crosscol .PopularPosts .item-thumbnail-only:hover .item-title a {
	visibility: visible;
	opacity: 1;
}
.crosscol .PopularPosts .item-title a {
	background:rgba(255,255,255,.85);
	width:90%;
	height:100%;
	text-decoration: none;
	position: absolute;
	text-align: center;
	left: 0;
	right: 0;
	top: 0;
	padding:30% 5% 30% 5%;
	opacity: 0;
	color:#666;
	font-weight:600;
	text-align:center;
	text-transform:uppercase;
	letter-spacing:1px;
	visibility: hidden;
	z-index:1;
}
.crosscol .PopularPosts .item-snippet {
	display:none;
}
.crosscol .PopularPosts .item-content {
	position: relative;
}
/* Posts */
.date-header {
	background:url(http://static.tumblr.com/haleqed/6ycnrauc8/icon-clock.png) left center no-repeat;
  	margin:0 auto;
	padding:0 15px;
	font-size:10px;
	font-weight:600;
  	text-transform:uppercase;
  	letter-spacing:1px;	
	color:#aaa;
}
.fn {
	background:url(http://static.tumblr.com/haleqed/bySnraugf/icon-author.png) left center no-repeat;
  	margin:0 auto;
	padding:0 15px;
	font-size:10px;
	font-weight:600;
  	text-transform:uppercase;
  	letter-spacing:1px;	
	color:#aaa;
}
.fn a {
	color:#aaa;
}
.comment-link {
	background:url(http://static.tumblr.com/haleqed/Blxnravjx/icon-comment.png) left center no-repeat;
  	margin:0 auto;
	padding:0 15px;
	font-size:10px;
	font-weight:600;
  	text-transform:uppercase;
  	letter-spacing:1px;	
	color:#aaa;
}
.post {
	background:#FFF;
  	margin:0 auto;
  	padding:10px 10px 50px 10px;
}
.post h3 {
  	margin:.25em 0 0;
  	padding:0 0 4px;
}
.post h3 a, .post h3 a:visited, .post h3 strong {
  	display:block;
  	text-decoration:none;
  	color:#222;
}
.post h3 strong, .post h3 a:hover {
  	color:#666;
}
.post-body {
  	margin:30px auto 80px;
  	line-height:21px;
	text-align:justify;
	font-size:13px;
}
.post img, table.tr-caption-container {
	max-width:680px;
	height:auto;
}
.tr-caption-container img {
  	border: none;
  	padding: 0;
}
.tr-caption, .legend {
	border-left:1px solid #EEE;
	border-bottom:1px solid #EEE;
	padding:10px 20px 10px 20px;
	margin:0 auto 30px;
	font-style:italic;
}
.post blockquote {
  	margin:20px;
	padding:30px;
	border:1px solid #333;
}
.post-body blockquote {
  	line-height:21px;  
	font-style:italic;
	font-size:14px;
}
.post ul {
	margin:5px 10px 5px;
}
.post li {
	list-style:square;
  	font-size:12px;
  	margin:5px 20px 5px;
}
.jump-link {
	background:#EEE;
	width:120px;
	margin:-60px auto 80px;
	padding:15px 20px 15px 20px;
	text-align:center;
	text-transform:uppercase;
}
.jump=link a:hover {
	background:#999;
}
.post-footer {
  	border-top:1px solid #CCC;
	padding:20px auto 20px;
	font-size:10px;
	font-weight:600;
  	text-transform:uppercase;
  	letter-spacing:1px;	
	color:#999;
}
.post-footer-line-2 {
  	margin:0 auto;
	padding:10px 0 0 15px;
	float:right;
}
.post-footer a, 
.post-footer a:visited {
	color:#999;
}
.post-footer a:hover {
	color:#111;
}
.compartilhar {
	background:#FFF;
	float:left;
	width:20%;
	height:16px;
	margin:-10px auto;
}
.compartilhar li {
	float:left;
	margin:0 13px;
	list-style:none;
	opacity:.5;
}
.compartilhar li:hover {
	opacity:1;
}
.twitter {
	background:url(http://static.tumblr.com/haleqed/ELMnravck/twitter.png) center no-repeat;
	width:16px;
	height:16px;
}
.facebook {
	background:url(http://static.tumblr.com/haleqed/zCcnravb4/facebook.png) center no-repeat;
	width:16px;
	height:16px;
}
.google {
	background:url(http://static.tumblr.com/haleqed/PRynravcp/google.png) center no-repeat;
	width:16px;
	height:16px;
}
/* Postagens relacionadas */
#at-gambar{
	padding:0 10px 0 10px;
	margin:0 0 80px;
	overflow:hidden;
	font-size:10px;
	font-weight:400;
  	text-transform:uppercase;
  	letter-spacing:1px;	
	text-align:center;
}
#at-gambar h2 {
	display:none;
}
#at-gambar a{
	color:#666;
	padding:5px;
	overflow:hidden;
	opacity:.8;
	float:left;
}
#at-gambar a img{
	width:120px;
	height:118px;
}
.box-related{
	width:120px;
	padding-left:3px;
	height:50px;
	border:0px none;
	margin:0 0 5px
	padding:0pt;
	line-height:normal;
	font-stretch:normal;
}
#at-gambar a:hover{
	opacity:1;
}
#at-gambar img{
	width:100%;
	margin:0;
	padding:0
}
#posting{
	width:auto !important;
	max-width:100%;
	margin:15px 20px 15px 0px;
}
/* Sidebar Content */
.sidebar { 
	margin:0;
  	color:#222;
	font-weight:300;
  	line-height:18px;
	font-size:12px;
}
.sidebar .widget {
	background:#FFF;
  	margin:0 0 60px;
  	padding:15px;
	text-align:justify;
	border:5px solid #FAFAFA;
}
.sidebar h2 {
	background:#FFF;
	color:#333;
	margin:-25px auto 20px;
	padding:0 5px 0 5px;
	text-align:center;
}
.sidebar .widget-content img {
	max-width:270px;
	height:auto;
	margin:10px auto 10px;
}
.sidebar a,
.sidebar a:visited {
	color:#222;
	font-weight:400;
}
.sidebar a:hover {
	color:#999;
	font-weight:400;
}
.sidebar ul {
  	margin:0 10px;
  	padding:0;
}
.sidebar li {
	color:#666;
  	list-style:square;
  	margin:0 10px 10px;
  	padding:5px 5px 5px 20px;
  	text-indent:-15px;
  	line-height:100$;
}
/* Comments */
.comment-content {
	width:700px;
	margin:10px 0 20px;
	line-height:21px;
	font-size:12px;
	font-family:'Open Sans',sans-serif;
	color:#666;
}
.comments {
	background:#FFF;
	width:680px;
	margin:20px auto;
	padding:10px;
}
.comment-header {
	width:100%;
	height:26px;
}
.comments .comments-content .user {
	margin:10px auto;
	font-weight:300;
	letter-spacing:1px;
	font-size:16px;
	text-transform:uppercase;
	font-family:'Open Sans',sans-serif;
	color:#333;
}
#comments-block .comment-body {
	margin:10px 0 30px;
}
.comments-content .datetime {
	text-align:right;
	text-transform:uppercase;
	letter-spacing:1px;
	font-size:10px;
}
.comment-actions secondary-text {
	margin:30px auto 10px;
	line-height:18px;
	text-transform:uppercase;
	letter-spacing:1px;
}
.comments .comments-replybox {
	max-width:720px;
}
.comments .comment .comment-actions a,
.comments .comment .continue a {
	background:#EEE;
	padding:7px 5px 7px 5px;
	margin:30px 10px;
	cursor: pointer;
	text-transform:uppercase;
	letter-spacing:1px;
	font-size:10px;
}
.comments .comment .comment-actions a:hover,
.comments .comment .continue a:hover {
	text-decoration:none;
	background:#CCC;
}
.continue .comments .comment .comment-actions a,
.comments .comment .continue a {
	background:none;
	margin:20px auto 50px;
	font-size:11px;
}
.continue .comments .comment .comment-actions a:hover,
.comments .comment .continue a:hover {
	text-decoration:none;
	background:none;
}
#comments-block .comment-footer {
	margin:10px 0 10px;
	line-height:18px;
	text-transform:uppercase;
	letter-spacing:1px;
}
#comments-block .comment-body p {
	margin:0 0 30px;
}
.avatar-image-container{
	float:left;
	margin:0 30px 30px 0;
	vertical-align:middle;
	overflow:hidden;
	max-width:50px;
	max-height:50px;
	min-width:50px;
	min-height:50px;
	padding:5px;
} 
.comments .avatar-image-container img {
	float:left;
	margin:0 30px 30px 0;
	vertical-align:middle;
	overflow:hidden;
	max-width:40px;
	max-height:40px;
	min-width:40px;
	min-height:40px;
	padding:3px;
	border:1px solid #f0f0f0;
}
.deleted-comment {
	font-style:italic;
	color:gray;
}
/* Paginação */
#blog-pager-newer-link {
  	float:right;
	background:url(http://static.tumblr.com/haleqed/rQOnrbwjy/right_arrow_24.png) right no-repeat;
	height:24px;
	padding:0 30px;
	line-height:28px;
} 
#blog-pager-older-link {
  	float:left;
	background:url(http://static.tumblr.com/haleqed/L0snrbwgn/left_arrow_on_circle_24.png) left no-repeat;
	height:24px;
	padding:0 30px;
	line-height:28px;
}
#home-link {
	padding:0 30px;
	line-height:28px;
}
#blog-pager { 
	width:100%;
	height:24px;
	padding:10px 0 10px;
	margin:0 auto;
  	text-align:center;
	text-transform:uppercase;
	font-size:9px;
	letter-spacing:1px;
	color:#666;
}
#blog-pager a {
	color:#666;
}
.feed-links {
  	display:none;
}
/* Footer */
.footer {
	width:1050px;
	margin:0 auto;
	padding:0;
	font-weight:400;
	font-size:11px;
}
#creditos {
	background:#333;
  	width:100%
	height:30px;
  	margin:0 0 -20px 0;
	padding:0 0 0 0;
}
.creditos {
	padding:10px;
  	text-align:center;
	font-weight:600;
	text-transform:uppercase;
	letter-spacing:1px;
	font-size:10px;
	color:#EEE;
}

head.script:

var defaultnoimage = "http://3.bp.blogspot.com/-zP87C2q9yog/UVopoHY30SI/AAAAAAAAE5k/AIyPvrpGLn8/s100/picture_not_available.png";
var maxresults = 5; 
var splittercolor = "#d3d3d3 "; 
var relatedpoststitle = "Posts Relacionados :";

b:if.script:
